import{b as e,Y as t,O as a,g as o,l as r}from"./chunks/framework.DcaUmd3X.js";const f=JSON.parse('{"title":"端正学习态度","description":"","frontmatter":{"layout":"page","title":"端正学习态度","aside":false,"mindmap":"# 端正学习态度\\n## 学习的两种层次\\n- 主动学习\\n- 被动学习\\n\\n## 浅度学习\\n- 学习不是努力读更多的书\\n- 避免快餐信息，与成长的幻觉\\n\\n## 深度学习\\n- 高质量的信息源和第一手知识\\n- 把知识连成地图，将自己的理解反述出来\\n- 不断地思考和思辨，与不同年龄段的人讨论\\n- 举一反三，并践行之，把知识转换成技能\\n\\n## 学习是逆人性的事情，就像锻炼身体一样，需要人持续付出，会让人感到痛苦，并随时想找理由放弃。\\n\\n## 学习不仅仅是为了找到答案，而更是为了找到方法\\n\\n## 学习是为了找到原理\\n\\n## 学习是为了了解自己\\n- 开拓眼界的目的就是发现自己的不足和上升空间，从而才能让自己成长\\n\\n## 学习是为了改变自己\\n"},"headers":[],"relativePath":"knowledge-graph/right-learning-attitude/index.md","filePath":"知识图谱/1.端正学习态度.md","lastUpdated":1782289777000}'),d={name:"knowledge-graph/right-learning-attitude/index.md"};function i(s,p,_,l,c,m){const n=t("MindmapPage");return a(),o("div",null,[r(n)])}const h=e(d,[["render",i]]);export{f as __pageData,h as default};
